            state=config.Revision.State.APPLYING,
            state_detail="state_detail_value",
            error_code=config.Revision.ErrorCode.CLOUD_BUILD_PERMISSION_DENIED,
            build="build_value",
            logs="logs_value",
            error_logs="error_logs_value",
            service_account="service_account_value",
