def test_list_previews_pager(transport_name: str = "grpc"):
    client = ConfigClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(type(client.transport.list_previews), "__call__") as call:
        # Set the response to a series of pages.
        call.side_effect = (
            config.ListPreviewsResponse(
                previews=[
                    config.Preview(),
                    config.Preview(),
                    config.Preview(),
                ],
                next_page_token="abc",
            ),
            config.ListPreviewsResponse(
                previews=[],
                next_page_token="def",
            ),
            config.ListPreviewsResponse(
                previews=[
                    config.Preview(),
                ],
                next_page_token="ghi",
            ),
            config.ListPreviewsResponse(
                previews=[
                    config.Preview(),
                    config.Preview(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_previews(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, config.Preview) for i in results)


