def test_config_base_transport():
    # Instantiate the base transport.
    with mock.patch(
        "google.cloud.config_v1.services.config.transports.ConfigTransport.__init__"
    ) as Transport:
        Transport.return_value = None
        transport = transports.ConfigTransport(
            credentials=ga_credentials.AnonymousCredentials(),
        )

    # Every method on the transport should just blindly
    # raise NotImplementedError.
    methods = (
        "list_deployments",
        "get_deployment",
        "create_deployment",
        "update_deployment",
        "delete_deployment",
        "list_revisions",
        "get_revision",
        "get_resource",
        "list_resources",
        "export_deployment_statefile",
        "export_revision_statefile",
        "import_statefile",
        "delete_statefile",
        "lock_deployment",
        "unlock_deployment",
        "export_lock_info",
        "create_preview",
        "get_preview",
        "list_previews",
        "delete_preview",
        "export_preview_result",
        "list_terraform_versions",
        "get_terraform_version",
        "list_resource_changes",
        "get_resource_change",
        "list_resource_drifts",
        "get_resource_drift",
        "get_auto_migration_config",
        "update_auto_migration_config",
        "get_deployment_group",
        "create_deployment_group",
        "update_deployment_group",
        "delete_deployment_group",
        "list_deployment_groups",
        "provision_deployment_group",
        "deprovision_deployment_group",
        "get_deployment_group_revision",
        "list_deployment_group_revisions",
        "set_iam_policy",
        "get_iam_policy",
        "test_iam_permissions",
        "get_location",
        "list_locations",
        "get_operation",
        "cancel_operation",
        "delete_operation",
        "list_operations",
    )
    for method in methods:
        with pytest.raises(NotImplementedError):
            getattr(transport, method)(request=object())

    with pytest.raises(NotImplementedError):
        transport.close()

    # Additionally, the LRO client (a property) should
    # also raise NotImplementedError
    with pytest.raises(NotImplementedError):
        transport.operations_client

    # Catch all for all remaining methods and properties
    remainder = [
        "kind",
    ]
    for r in remainder:
        with pytest.raises(NotImplementedError):
            getattr(transport, r)()


